/**
 * One edited row in {@link Changes}: the row's key and the fields whose value differs from the
 * original, with their new value.
 *
 * The key is under the name of the key field (`id` with `new Datasource({ key: 'id' })`), or under
 * `__KEY` when the datasource has no key - then it is a generated negative number, a server can not
 * use it.
 *
 * A field edited back to its original value is not in it, and a row with no field left that
 * differs is not edited. When a value differs depends on the field's type, see {@link Changes}.
 *
 * @example
 * ```ts
 * import { Datasource } from '@simple-html/grid';
 *
 * interface Person {
 *     id: number;
 *     name: string;
 *     city: string;
 * }
 *
 * const datasource = new Datasource<Person>({ key: 'id' });
 * datasource.setData([{ id: 7, name: 'Ann', city: 'Oslo' }]);
 * datasource.getDataRows()[0].city = 'Bergen';
 *
 * datasource.getChanges().modifiedEntities; // [{ id: 7, city: 'Bergen' }]
 * ```
 */
export type ModifiedEntity<T> = Partial<T> & {
    /** the generated key, only when the datasource has no key field */
    __KEY?: string | number;
};

/**
 * What `datasource.getChanges()` returns: the rows added, edited and marked for deletion since the
 * data was set - what to send to a server.
 *
 * - `newEntities` - rows added with `addNewEmpty()`, edits to them included. A new row has a
 *   temporary key, a generated negative number: in its key field (`id: -1`), or as `__KEY` when the
 *   datasource has no key field. After the save, `acceptChanges({ newKeys })` gives the rows the
 *   server's keys
 * - `modifiedEntities` - one entry per edited row: its key and the changed fields, see
 *   {@link ModifiedEntity}
 * - `deletedEntities` - rows marked with `markForDeletion()` / `markAllForDeletion()`. A new row
 *   that is marked for deletion is in none of the lists: it was never saved, there is nothing to send.
 *
 * Every entry is a copy, a plain object: changing it does not change the row. It is a shallow copy -
 * a `Date` stays a `Date`, an object in a field is the row's own object.
 *
 * When an edit counts: a field is edited when its value differs from the original. A field set back
 * to its original value is not edited any more. Setting a blank field (`null` / `undefined`) to `''`
 * is no edit. Two `Date`s are compared by the field's type in the datasource's `fields`:
 *
 * - `date` - on the day. A date typed into a cell gets the current time of day, so typing the same
 *   day again is no edit.
 * - `datetime`, and every other field - to the second, the milliseconds are ignored (they are not
 *   shown, and typing a time stamps the current ones). A time only change is an edit.
 *
 * @sample editing
 * @example
 * ```ts
 * import { Datasource } from '@simple-html/grid';
 *
 * interface Person {
 *     id: number;
 *     name: string;
 *     born: Date | null;
 *     lastLogin: Date | null;
 * }
 * declare const rowsFromServer: Person[];
 *
 * const datasource = new Datasource<Person>({ key: 'id', fields: { born: 'date', lastLogin: 'datetime' } });
 * datasource.setData(rowsFromServer);
 * // ... the user edits, adds and deletes rows in the grid
 *
 * const { newEntities, modifiedEntities, deletedEntities } = datasource.getChanges();
 * const response = await fetch('/api/people', {
 *     method: 'POST',
 *     body: JSON.stringify({ newEntities, modifiedEntities, deletedEntities }) // a Date becomes its ISO text
 * });
 *
 * // saved in one transaction: the server answers with the id it gave each new row
 * const saved: { temporaryId: number; id: number }[] = await response.json();
 * datasource.acceptChanges({ newKeys: new Map(saved.map((row) => [row.temporaryId, row.id])) });
 * ```
 */
export interface Changes<T = Record<string, unknown>> {
    /**
     * the rows added with `addNewEmpty()` (or the container's `setData(rows, { add: true, isNew: true })`),
     * with the values they have now. Without a key field the temporary key is in `__KEY`
     */
    newEntities: (T & {
        /** the temporary key, a generated negative number - only when the datasource has no key field */
        __KEY?: string | number;
    })[];
    /** one entry per edited row: its key and the fields that changed */
    modifiedEntities: ModifiedEntity<T>[];
    /** the rows marked for deletion, with the values they have now */
    deletedEntities: T[];
}

/**
 * Which kinds of change `getChanges()`, `hasChanges()` and `getChangedRows()` look at:
 *
 * - left out, or `null` - all of them
 * - kinds set to `true` - only those: `{ new: true }` the new rows, `{ new: true, modified: true }` what a
 *   save of the rows sends without the deletions
 * - only kinds set to `false` - all but those: `{ deleted: false }` is the new and edited rows
 *
 * A kind left out is not asked for: with a kind `true` it is left out, with only kinds `false` it is in.
 * `getChanges()` keeps its three lists, a kind not asked for is `[]`.
 *
 * @example
 * ```ts
 * import { Datasource } from '@simple-html/grid';
 *
 * const datasource = new Datasource({ key: 'id' });
 * datasource.getChanges({ deleted: true }).deletedEntities; // only the rows marked for deletion
 * datasource.hasChanges({ new: true, modified: true }); // added or edited rows, not deletions
 * datasource.getChangedRows({ deleted: false }); // the new and edited rows themselves
 * ```
 */
export interface ChangeKinds {
    /** the rows added (`addNewEmpty()`, `__rowState` `'N'`) */
    new?: boolean | null;
    /** the rows edited (`'M'`) */
    modified?: boolean | null;
    /** the rows marked for deletion (`'D'`) - not a new row marked: it was never saved */
    deleted?: boolean | null;
}

/** the kind of change of a row, as ChangeKinds names it */
export type ChangeKind = 'new' | 'modified' | 'deleted';

/**
 * @internal
 * The kinds ChangeKinds asks for: all for none (null, undefined, `{}`); the ones `true` when one is;
 * else all but the ones `false`
 * @throws a `TypeError` for what is no object of `new`, `modified`, `deleted` - booleans, null or left out
 */
export function changeKindsOf(kinds: ChangeKinds | null | undefined): Set<ChangeKind> {
    const all: ChangeKind[] = ['new', 'modified', 'deleted'];
    if (kinds === null || kinds === undefined) {
        return new Set(all);
    }
    if (typeof kinds !== 'object' || Array.isArray(kinds)) {
        throw new TypeError(`the kinds of change are { new?, modified?, deleted? }, got ${JSON.stringify(kinds)}`);
    }
    for (const [name, value] of Object.entries(kinds)) {
        if (!all.includes(name as ChangeKind)) {
            throw new TypeError(`'${name}' is no kind of change, they are new, modified and deleted`);
        }
        if (value !== undefined && value !== null && typeof value !== 'boolean') {
            throw new TypeError(`${name} is true, false or null, got ${JSON.stringify(value)}`);
        }
    }
    const picked = all.filter((kind) => kinds[kind] === true);
    return new Set(picked.length ? picked : all.filter((kind) => kinds[kind] !== false));
}
